using namespace std;

// ==========================================
// ENUMS & CONSTANTS
// ==========================================
enum ItemStatus {
    LOST,
    FOUND,
    CLAIMED
};

enum Category {
    ELECTRONICS,
    BOOKS,
    STATIONERY,
    CLOTHING,
    MISCELLANEOUS
};

// ==========================================
// STRUCT: Date
// Simple structure to handle dates
// ==========================================
struct Date {
    int day;
    int month;
    int year;

    Date(int d, int m, int y) : day(d), month(m), year(y) {}
    Date() : day(1), month(1), year(2026) {}

    string toString() const {
        string d = (day < 10) ? "0" + to_string(day) : to_string(day);
        string m = (month < 10) ? "0" + to_string(month) : to_string(month);
        return d + "/" + m + "/" + to_string(year);
    }
};

// ==========================================
// CLASS: CampusItem
// Represents an item in the Lost & Found system
// ==========================================
class CampusItem {
private:
    string itemId;
    string itemName;
    Category itemCategory;
    string description;
    string location;
    Date dateReported;
    ItemStatus status;
    string reporterContact; // Student Roll Number or Phone

public:
    CampusItem(string id, string name, Category cat, string desc, 
               string loc, Date d, ItemStatus stat, string contact) {
        itemId = id;
        itemName = name;
        itemCategory = cat;
        description = desc;
        location = loc;
        dateReported = d;
        status = stat;
        reporterContact = contact;
    }

    // Getters
    string getId() const { return itemId; }
    string getName() const { return itemName; }
    ItemStatus getStatus() const { return status; }
    string getContact() const { return reporterContact; }

    // Setters
    void setStatus(ItemStatus newStatus) { status = newStatus; }

    // Helper to get category as string
    string getCategoryString() const {
        switch (itemCategory) {
            case ELECTRONICS: return "Electronics";
            case BOOKS: return "Books/Notes";
            case STATIONERY: return "Stationery";
            case CLOTHING: return "Clothing";
            default: return "Miscellaneous";
        }
    }

    // Helper to get status as string
    string getStatusString() const {
        switch (status) {
            case LOST: return "LOST";
            case FOUND: return "FOUND";
            case CLAIMED: return "CLAIMED";
            default: return "UNKNOWN";
        }
    }

    // Display formatted item details
    void displayItem() const {
        cout << left << setw(10) << itemId 
             << setw(20) << itemName 
             << setw(15) << getCategoryString() 
             << setw(15) << location 
             << setw(12) << dateReported.toString() 
             << setw(10) << getStatusString() << endl;
    }

    void displayDetailed() const {
        cout << "\n--- Item Details [" << itemId << "] ---" << endl;
        cout << "Name:        " << itemName << endl;
        cout << "Category:    " << getCategoryString() << endl;
        cout << "Description: " << description << endl;
        cout << "Location:    " << location << endl;
        cout << "Date:        " << dateReported.toString() << endl;
        cout << "Status:      " << getStatusString() << endl;
        cout << "Contact:     " << reporterContact << endl;
        cout << "----------------------------------" << endl;
    }
};

// ==========================================
// CLASS: LostAndFoundManager
// Orchestrates the database of items
// ==========================================
class LostAndFoundManager {
private:
    vector<CampusItem> database;
    int nextIdCounter;

    string generateId() {
        string id = "ITM" + to_string(nextIdCounter);
        nextIdCounter++;
        return id;
    }

public:
    LostAndFoundManager() {
        nextIdCounter = 1001;
    }

    // Add a new lost item report
    void reportLostItem(string name, Category cat, string desc, string loc, Date d, string contact) {
        string newId = generateId();
        CampusItem newItem(newId, name, cat, desc, loc, d, LOST, contact);
        database.push_back(newItem);
        cout << "[SUCCESS] Lost item reported. ID: " << newId << endl;
    }

    // Add a new found item report
    void reportFoundItem(string name, Category cat, string desc, string loc, Date d, string contact) {
        string newId = generateId();
        CampusItem newItem(newId, name, cat, desc, loc, d, FOUND, contact);
        database.push_back(newItem);
        cout << "[SUCCESS] Found item logged safely. ID: " << newId << endl;
    }

    // Process a claim
    void claimItem(string id, string claimantContact) {
        for (auto& item : database) {
            if (item.getId() == id) {
                if (item.getStatus() == CLAIMED) {
                    cout << "[ERROR] Item " << id << " has already been claimed." << endl;
                    return;
                }
                if (item.getStatus() == LOST) {
                    cout << "[ERROR] Item " << id << " is marked as LOST, not FOUND." << endl;
                    return;
                }

                // Approve claim
                item.setStatus(CLAIMED);
                cout << "[SUCCESS] Item " << id << " successfully claimed by " << claimantContact << "." << endl;
                return;
            }
        }
        cout << "[ERROR] Item ID " << id << " not found in database." << endl;
    }

    // Display all active (unclaimed) items
    void displayActiveBulletin() const {
        cout << "\n==========================================================================" << endl;
        cout << "                      CAMPUS ACTIVE BULLETIN BOARD                        " << endl;
        cout << "==========================================================================" << endl;
        cout << left << setw(10) << "ID" 
             << setw(20) << "Item Name" 
             << setw(15) << "Category" 
             << setw(15) << "Location" 
             << setw(12) << "Date" 
             << setw(10) << "Status" << endl;
        cout << "--------------------------------------------------------------------------" << endl;

        int count = 0;
        for (const auto& item : database) {
            if (item.getStatus() != CLAIMED) {
                item.displayItem();
                count++;
            }
        }

        if (count == 0) {
            cout << "No active items reported." << endl;
        }
        cout << "==========================================================================" << endl;
    }

    // Search for an item by keyword in the name
    void searchByName(string keyword) const {
        cout << "\n--- Search Results for '" << keyword << "' ---" << endl;

        // Convert keyword to lowercase for basic case-insensitive search
        string lowerKeyword = keyword;
        transform(lowerKeyword.begin(), lowerKeyword.end(), lowerKeyword.begin(), ::tolower);

        bool foundAny = false;
        for (const auto& item : database) {
            string lowerName = item.getName();
            transform(lowerName.begin(), lowerName.end(), lowerName.begin(), ::tolower);

            if (lowerName.find(lowerKeyword) != string::npos) {
                item.displayDetailed();
                foundAny = true;
            }
        }

        if (!foundAny) {
            cout << "No items found matching the description." << endl;
        }
    }
};

// ==========================================
// MAIN FUNCTION (Simulation Script)
// ==========================================
int main() {
    cout << "Initializing Campus Central Database..." << endl;
    LostAndFoundManager manager;

    // 1. Simulate students reporting lost items
    cout << "\n[Simulating Data Entry: Lost Items]" << endl;
    manager.reportLostItem("MacBook Air M3", ELECTRONICS, "Silver, 15-inch, black sleeve", "Library 2nd Floor", Date(14, 4, 2026), "24CSB0A58");
    manager.reportLostItem("Physics Textbook", BOOKS, "Resnick Halliday, Blue cover", "Academic Block B", Date(15, 4, 2026), "24ECB1B22");

    // 2. Simulate students turning in found items
    cout << "\n[Simulating Data Entry: Found Items]" << endl;
    manager.reportFoundItem("Apple AirPods Pro", ELECTRONICS, "White case, small scratch on back", "Cafeteria", Date(16, 4, 2026), "AdminOffice");
    manager.reportFoundItem("Titan Wristwatch", MISCELLANEOUS, "Silver strap, analog dial", "Sports Complex", Date(17, 4, 2026), "AdminOffice");
    manager.reportFoundItem("Water Bottle", MISCELLANEOUS, "Milton, Black, 1 Litre", "Lab Complex", Date(18, 4, 2026), "AdminOffice");

    // 3. Display the bulletin board
    manager.displayActiveBulletin();

    // 4. Simulate a student searching for their lost AirPods
    manager.searchByName("AirPods");

    // 5. Simulate a successful claim
    cout << "\n[Simulating Claim Process]" << endl;
    manager.claimItem("ITM1003", "24EEB0C11"); // Claiming the AirPods

    // 6. Simulate an invalid claim (trying to claim something already claimed)
    manager.claimItem("ITM1003", "24MEB2D44"); 

    // 7. Final board display to ensure the claimed item is removed
    cout << "\n[Final Bulletin Board State]" << endl;
    manager.displayActiveBulletin();

    cout << "\nSimulation Complete. System shutting down gracefully." << endl;
    return 0;
}

