// Represents an item in the Lost & Found system
// ==========================================
class CampusItem {
private:
    string itemId;
    string itemName;
    Category itemCategory;
    string description;
    string location;
    Date dateReported;
    ItemStatus status;
    string reporterContact; // Student Roll Number or Phone

